import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import SmartToyOutlinedIcon from '@mui/icons-material/SmartToyOutlined';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import ApiService from '../services/api';
import useAppTranslation from '../hooks/useAppTranslation';
import { t as translateLocale } from '../i18n/index';
import { AUTH_TOKEN_CHANGED_EVENT } from '../constants/authEvents';
import { MSME_MOBILE_BOTTOM_NAV_HEIGHT } from './MsmeMobileBottomNav';

type ChatRole = 'user' | 'assistant';

type ChatMessage = {
  id: string;
  role: ChatRole;
  text: string;
  suggestedRoute?: string | null;
  intent?: string | null;
  sources?: string[];
};

type SavedConversation = {
  id: string;
  title: string;
};

type SavedMessage = {
  id: string;
  role: ChatRole;
  text: string;
  status?: string;
  suggestedRoute?: string | null;
  sources?: string[];
};

const SUGGESTED_PROMPTS = [
  'How much water did we save this month?',
  'Why did our carbon footprint increase?',
  'What are the three highest-impact actions?',
  'How much will we save if we install solar?',
  'Prepare our sustainability action plan for FY27.',
  'Find the cheapest way to reduce emissions by 20%.',
];

const createId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

const EMPTY_HEADING = {
  en: 'What should we look at?',
  hi: 'क्या देखना चाहेंगे?',
} as const;

type CarbonCopilotPageProps = {
  /** Chat panel inside the floating advisor. The full-page header and height are omitted. */
  embedded?: boolean;
};

/**
 * AI Advisor — organisation sustainability Q&A (footprint, water, hotspots, solar, plans).
 */
const CarbonCopilotPage: React.FC<CarbonCopilotPageProps> = ({ embedded = false }) => {
  const { t, locale } = useAppTranslation();
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [conversations, setConversations] = useState<SavedConversation[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const listRef = useRef<HTMLDivElement | null>(null);
  const loadSeq = useRef(0);
  const draftNewRef = useRef(false);
  const localTurnRef = useRef(false);

  const savedToChat = (message: SavedMessage): ChatMessage => ({
    id: message.id,
    role: message.role,
    text: message.text,
    suggestedRoute: message.suggestedRoute || null,
    sources: message.sources || [],
  });

  const loadHistory = useCallback(async () => {
    const seq = ++loadSeq.current;
    const historyErrorText = translateLocale('copilot.historyError', locale);
    setHistoryLoading(true);
    setHistoryError(null);
    try {
      const response = await ApiService.listCopilotConversations();
      if (seq !== loadSeq.current) return;
      if (!response?.success) {
        setHistoryError(response?.message || historyErrorText);
        return;
      }
      const items = (response.data?.conversations || []) as SavedConversation[];
      setConversations(items);
      if (draftNewRef.current || localTurnRef.current) return;
      const latest = items[0];
      if (!latest) {
        setConversationId(null);
        setMessages([]);
        return;
      }
      const detail = await ApiService.getCopilotConversation(latest.id);
      if (seq !== loadSeq.current || draftNewRef.current) return;
      if (!detail?.success) {
        setHistoryError(detail?.message || historyErrorText);
        return;
      }
      const conversation = detail.data?.conversation;
      setConversationId(conversation?.id || latest.id);
      setMessages((conversation?.messages || []).map(savedToChat));
    } catch (err) {
      if (seq !== loadSeq.current) return;
      setHistoryError(err instanceof Error ? err.message : historyErrorText);
    } finally {
      if (seq === loadSeq.current) setHistoryLoading(false);
    }
  }, [locale]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, loading]);

  useEffect(() => {
    void loadHistory();
    const onAuth = () => {
      draftNewRef.current = false;
      localTurnRef.current = false;
      setMessages([]);
      setConversationId(null);
      setConversations([]);
      void loadHistory();
    };
    window.addEventListener(AUTH_TOKEN_CHANGED_EVENT, onAuth);
    return () => window.removeEventListener(AUTH_TOKEN_CHANGED_EVENT, onAuth);
  }, [loadHistory]);

  const canSend = useMemo(() => input.trim().length > 0 && !loading, [input, loading]);

  const ask = async (rawMessage: string) => {
    const message = rawMessage.trim();
    if (!message || loading) return;

    setError(null);
    setInput('');
    localTurnRef.current = true;
    setMessages((prev) => [...prev, { id: createId(), role: 'user', text: message }]);
    setLoading(true);

    try {
      const clientMessageId = createId();
      const response = await ApiService.askCarbonCopilot(message, {
        conversationId,
        clientMessageId,
      });
      if (!response?.success) {
        throw new Error(response?.message || t('copilot.questionFailed'));
      }
      const payload = (response.data || {}) as {
        answer?: string;
        reply?: string;
        suggestedRoute?: string;
        intent?: string;
        sources?: string[];
      };
      const answer = String(payload.answer || payload.reply || '').trim() || t('copilot.noAnswer');
      setMessages((prev) => [
        ...prev,
        {
          id: createId(),
          role: 'assistant',
          text: answer,
          suggestedRoute: payload.suggestedRoute || null,
          intent: payload.intent || null,
          sources: payload.sources || [],
        },
      ]);
      const savedId = (response.data as { conversationId?: string; historySaved?: boolean } | undefined)?.conversationId;
      if (savedId) {
        setConversationId(savedId);
        setConversations((current) => (
          current.some((item) => item.id === savedId)
            ? current
            : [{ id: savedId, title: message }, ...current]
        ));
      }
      if ((response.data as { historySaved?: boolean } | undefined)?.historySaved === false) {
        setHistoryError(t('copilot.historySaveError'));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : t('copilot.questionFailed'));
      setMessages((prev) => [
        ...prev,
        {
          id: createId(),
          role: 'assistant',
          text: t('copilot.questionFailed'),
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const showWelcome = messages.length === 0 && !loading;

  const promptChips = (compact: boolean) => {
    const chips = SUGGESTED_PROMPTS.map((prompt) => (
      <Chip
        key={prompt}
        label={prompt}
        clickable
        disabled={loading}
        onClick={() => void ask(prompt)}
        variant="outlined"
        sx={{
          display: 'flex',
          width: compact ? 'auto' : '100%',
          height: compact ? 'auto' : '100%',
          maxWidth: compact ? 280 : 'none',
          flexShrink: compact ? 0 : 1,
          justifyContent: 'flex-start',
          py: compact ? 0.75 : 1.125,
          px: compact ? 0 : 0.5,
          borderRadius: 2,
          bgcolor: 'background.paper',
          '& .MuiChip-label': {
            whiteSpace: 'normal',
            textAlign: 'left',
            lineHeight: 1.4,
            px: 1,
            py: 0.25,
            fontSize: '0.875rem',
          },
          '&:hover': {
            bgcolor: 'action.hover',
            borderColor: 'primary.main',
          },
          '&.Mui-disabled': {
            opacity: 0.7,
          },
        }}
      />
    ));

    if (compact) {
      return (
        <Stack
          direction="row"
          spacing={1}
          useFlexGap
          flexWrap="nowrap"
          sx={{ overflowX: 'auto', pb: 0.25 }}
        >
          {chips}
        </Stack>
      );
    }

    return (
      <Box
        sx={{
          display: 'grid',
          gap: 1.25,
          gridTemplateColumns: '1fr',
          alignItems: 'stretch',
          '@container (min-width: 520px)': {
            gridTemplateColumns: '1fr 1fr',
          },
        }}
      >
        {chips}
      </Box>
    );
  };

  // App bar 56/64, container padding, main padding, and the fixed mobile nav.
  // Height keeps the composer inside the scrolling column instead of below it.
  const pageHeight = {
    xs: `calc(100dvh - 56px - 20px - ${MSME_MOBILE_BOTTOM_NAV_HEIGHT}px - 24px - 8px - env(safe-area-inset-bottom, 0px))`,
    md: 'calc(100dvh - 64px - 24px - 32px - 24px)',
  };

  return (
    <Box
      data-testid={embedded ? 'ai-advisor-chat' : 'ai-advisor-page'}
      sx={{
        display: 'flex',
        flexDirection: 'column',
        height: embedded ? '100%' : pageHeight,
        maxHeight: embedded ? '100%' : pageHeight,
        minHeight: 0,
        overflow: 'hidden',
      }}
    >
      {embedded ? null : (
        <WorkspacePageHeader
          title={t('copilot.title')}
          description={t('copilot.subtitle')}
        />
      )}

      <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mb: 1, alignItems: 'center' }}>
        <Button size="small" variant="outlined" onClick={() => {
          draftNewRef.current = true;
          loadSeq.current += 1;
          setConversationId(null);
          setMessages([]);
          setError(null);
          setHistoryError(null);
        }}
        >
          {t('copilot.newConversation')}
        </Button>
        <Button
          size="small"
          variant="outlined"
          disabled={!conversationId || loading}
          onClick={() => {
            if (!conversationId) return;
            void (async () => {
              const response = await ApiService.deleteCopilotConversation(conversationId);
              if (!response?.success) {
                setHistoryError(response?.message || t('copilot.historyError'));
                return;
              }
              draftNewRef.current = false;
              setConversationId(null);
              setMessages([]);
              await loadHistory();
            })();
          }}
        >
          {t('copilot.deleteConversation')}
        </Button>
        {historyLoading ? (
          <Typography variant="caption" color="text.secondary">{t('common.loading')}</Typography>
        ) : null}
      </Stack>
      {conversations.length > 0 ? (
        <Stack
          direction="row"
          spacing={1}
          useFlexGap
          flexWrap="wrap"
          aria-label={t('copilot.savedConversations')}
          sx={{ mb: 1 }}
        >
          {conversations.map((conversation) => (
            <Chip
              key={conversation.id}
              label={conversation.title}
              clickable
              color={conversation.id === conversationId ? 'primary' : 'default'}
              variant={conversation.id === conversationId ? 'filled' : 'outlined'}
              onClick={() => {
                draftNewRef.current = false;
                const seq = ++loadSeq.current;
                setHistoryLoading(true);
                void (async () => {
                  try {
                    const detail = await ApiService.getCopilotConversation(conversation.id);
                    if (seq !== loadSeq.current) return;
                    if (!detail?.success) {
                      setHistoryError(detail?.message || t('copilot.historyError'));
                      return;
                    }
                    const saved = detail.data?.conversation;
                    setConversationId(saved?.id || conversation.id);
                    setMessages((saved?.messages || []).map(savedToChat));
                    setError(null);
                  } catch (err) {
                    if (seq !== loadSeq.current) return;
                    setHistoryError(err instanceof Error ? err.message : t('copilot.historyError'));
                  } finally {
                    if (seq === loadSeq.current) setHistoryLoading(false);
                  }
                })();
              }}
            />
          ))}
        </Stack>
      ) : null}
      {historyError ? (
        <Alert severity="warning" sx={{ mb: 1 }}>{historyError}</Alert>
      ) : null}

      <Paper
        variant="outlined"
        sx={{
          flex: 1,
          minHeight: 0,
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
        }}
      >
        <Box
          ref={listRef}
          role="log"
          aria-live="polite"
          aria-relevant="additions"
          sx={{
            flex: 1,
            minHeight: 0,
            overflowY: 'auto',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: showWelcome ? 'safe center' : 'flex-start',
            p: { xs: 1.5, md: 2.5 },
            bgcolor: 'action.hover',
          }}
        >
          {showWelcome ? (
            <Box
              sx={{
                flexShrink: 0,
                containerType: 'inline-size',
                width: '100%',
                maxWidth: 680,
                mx: 'auto',
                px: { xs: 0.5, sm: 1 },
                py: 1,
                textAlign: 'center',
              }}
            >
              <Typography
                variant="subtitle1"
                component="h2"
                sx={{ fontWeight: 700, mb: 0.5, color: 'text.primary' }}
              >
                {EMPTY_HEADING[locale]}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2.5, lineHeight: 1.5 }}>
                {t('copilot.emptyHint')}
              </Typography>
              {promptChips(false)}
            </Box>
          ) : (
            <Stack spacing={2} sx={{ flexShrink: 0, width: '100%' }}>
              {messages.map((message) => {
                const isUser = message.role === 'user';
                return (
                  <Box
                    key={message.id}
                    sx={{
                      display: 'flex',
                      justifyContent: isUser ? 'flex-end' : 'flex-start',
                    }}
                  >
                    <Box
                      sx={{
                        maxWidth: { xs: '92%', md: 'min(75%, 72ch)' },
                        px: { xs: 1.5, md: 2 },
                        py: 1.5,
                        borderRadius: 2,
                        borderTopRightRadius: isUser ? 4 : undefined,
                        borderTopLeftRadius: isUser ? undefined : 4,
                        bgcolor: isUser ? 'primary.dark' : 'background.paper',
                        color: isUser ? 'primary.contrastText' : 'text.primary',
                        border: isUser ? 'none' : '1px solid',
                        borderColor: 'divider',
                      }}
                    >
                      {!isUser ? (
                        <Stack direction="row" spacing={0.75} alignItems="center" sx={{ mb: 0.75 }}>
                          <SmartToyOutlinedIcon sx={{ fontSize: 18 }} color="primary" />
                          <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 700 }}>
                            {t('copilot.title')}
                          </Typography>
                        </Stack>
                      ) : null}
                      <Typography
                        variant="body1"
                        sx={{
                          whiteSpace: 'pre-wrap',
                          overflowWrap: 'anywhere',
                          lineHeight: 1.65,
                          fontSize: { xs: '0.95rem', md: '1rem' },
                        }}
                      >
                        {message.text}
                      </Typography>
                      {message.suggestedRoute ? (
                        <Button
                          component={RouterLink}
                          to={message.suggestedRoute}
                          size="small"
                          sx={{ mt: 1.25 }}
                          variant="text"
                        >
                          {t('copilot.openSuggested')}
                        </Button>
                      ) : null}
                    </Box>
                  </Box>
                );
              })}
              {loading ? (
                <Stack direction="row" spacing={1} alignItems="center">
                  <CircularProgress size={16} />
                  <Typography variant="body2" color="text.secondary">
                    {t('copilot.thinking')}
                  </Typography>
                </Stack>
              ) : null}
            </Stack>
          )}
        </Box>

        {error ? (
          <Alert severity="error" sx={{ flexShrink: 0, mx: 1.5, mt: 1.5 }}>
            {error}
          </Alert>
        ) : null}

        {!showWelcome ? (
          <Box sx={{ flexShrink: 0, px: 1.5, pt: 1.25 }}>
            {promptChips(true)}
          </Box>
        ) : null}

        <Box sx={{ flexShrink: 0, p: { xs: 1.5, md: 2 }, borderTop: '1px solid', borderColor: 'divider' }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'flex-end' }}>
            <TextField
              fullWidth
              label={embedded ? undefined : t('copilot.questionLabel')}
              placeholder={t('copilot.questionPlaceholder')}
              inputProps={{ 'aria-label': t('copilot.questionLabel') }}
              value={input}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault();
                  void ask(input);
                }
              }}
              disabled={loading}
              multiline
              minRows={embedded ? 1 : 2}
              maxRows={embedded ? 4 : 6}
              sx={{
                '& .MuiInputBase-input': {
                  lineHeight: 1.5,
                  fontSize: '1rem',
                },
                '& .MuiOutlinedInput-root': {
                  bgcolor: 'background.paper',
                  '&.Mui-focused': {
                    boxShadow: (theme) => `0 0 0 3px ${theme.palette.primary.main}33`,
                  },
                  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                    borderColor: 'primary.main',
                    borderWidth: 2,
                  },
                  '&.Mui-disabled': {
                    bgcolor: 'action.hover',
                  },
                  '&.Mui-disabled .MuiOutlinedInput-notchedOutline': {
                    borderColor: 'divider',
                  },
                },
              }}
            />
            <Button
              variant="contained"
              startIcon={loading ? <CircularProgress size={16} color="inherit" /> : <SendIcon />}
              disabled={!canSend}
              onClick={() => void ask(input)}
              sx={{
                flexShrink: 0,
                minWidth: { xs: '100%', sm: 120 },
                minHeight: 48,
                px: 2.5,
                fontWeight: 700,
                boxShadow: 'none',
                bgcolor: 'primary.dark',
                color: 'primary.contrastText',
                '&:hover': {
                  bgcolor: 'primary.main',
                  boxShadow: 'none',
                },
                '&.Mui-focusVisible': {
                  outline: '2px solid',
                  outlineColor: 'background.paper',
                  outlineOffset: 2,
                  boxShadow: (theme) => `0 0 0 4px ${theme.palette.primary.dark}`,
                },
                '&.Mui-disabled': loading
                  ? {
                      bgcolor: 'primary.dark',
                      color: 'primary.contrastText',
                      opacity: 0.8,
                      border: '1px solid',
                      borderColor: 'transparent',
                      boxShadow: 'none',
                    }
                  : {
                      bgcolor: 'action.hover',
                      color: 'text.disabled',
                      border: '1px solid',
                      borderColor: 'divider',
                      boxShadow: 'none',
                    },
              }}
            >
              {t('copilot.ask')}
            </Button>
          </Stack>
        </Box>
      </Paper>
    </Box>
  );
};

export default CarbonCopilotPage;
